import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_already_on_the_step(self):
        self.assertEqual(
            round_spans([Span(540, 1035)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            round_spans([Span(544, 1031)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(round_spans([Span(547, 600)], 15)[0][:5], "09:00")
        self.assertEqual(round_spans([Span(548, 600)], 15)[0][:5], "09:15")

    def test_one_label_per_span_in_order(self):
        labels = round_spans([Span(600, 660), Span(60, 120)], 30)
        self.assertEqual(
            labels, ["10:00-11:00 (1h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 5), [])

    def test_short_span_can_collapse(self):
        self.assertEqual(
            round_spans([Span(541, 545)], 15), ["09:00-09:00 (0h 0m)"]
        )

    def test_end_of_day(self):
        self.assertEqual(
            round_spans([Span(1400, 1440)], 30), ["23:30-24:00 (0h 30m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 61, 7.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(len(round_spans([Span(60, 120)], step)), 1)


if __name__ == "__main__":
    unittest.main()
